s+=['','## Illustration-only colors','','These are literal colors found in the supplied vectors, not a complete product state specification. Error color semantics were not established.','','| Token | HEX | Observed context / suggested use |','| --- | --- | --- |']
for k,v in t['illustration'].items():
 context='Skills / workflow status or recommendation' if k.startswith(('mint','success','yellow')) else 'Governed-system domain or status' if k.startswith(('teal','blue','orange','sage')) else 'Homepage category accent'
 s.append(f'| `{k}` | `{v}` | {context} |')
s+=['','## Contrast measurements','','Calculated from sRGB relative luminance with `(Llighter + 0.05) / (Ldarker + 0.05)`. Targets used: 4.5:1 for normal text and 3:1 for essential non-text boundaries. Large text has a 3:1 target; bright pink on cream passes that threshold at 3.09:1, but fails the 4.5:1 normal-text target. Reserve it for qualifying large display text or decoration. These checks cover solid colors at full opacity, not overlays, photographic backgrounds, font legibility or whole-site conformance.','','| Pair | Foreground | Background | Ratio | Use |','| --- | --- | --- | --- | --- |']
for x in c:s.append(f"| {x['name']} | `{x['fg']}` | `{x['bg']}` | {x['ratio']}:1 | {'Passes selected target' if x['result']=='pass' else 'Not a default accessible text/control pair'} |")
s+=['','Use dark pink for text links and focus rings on light backgrounds. Use ink on bright pink. On inverse sections use pale pink links and focus indicators. Light taupe borders are decorative separators; use a stronger border for essential input boundaries. Never claim that all palette combinations are accessible.','', 'Supplied print CMYK recipes: Ink 71/68/67/84; Cream 0/2/4/2; Pink 0/78/13/0. No spot-color or printer-profile equivalence is implied. See docs/assets.md.']
(r/'docs/colors.md').write_text('\n'.join(s)+'\n')
